GLOSSARY = [
("ACE credit recommendation", "A recommendation from the American Council on Education about how much college credit a military course, occupation or workplace training program is worth, including level (lower- or upper-division), subject area and semester hours. Institutions decide whether and how to award the credit.", ["joint-services-transcript-jst", "credit-for-prior-learning-cpl"]),
("Articulation agreement", "A formal agreement between two institutions that specifies how courses or whole programs from one transfer to the other. Agreements reduce credit loss when they are applied consistently on every transcript.", ["transfer-credit-evaluation", "course-equivalency"]),
("Audit trail", "A permanent record of how a decision was made: the evidence reviewed, the rule applied, any recommendation and the person who approved it. In credit evaluation it supports appeals, accreditation and compliance reviews.", ["human-in-the-loop-review"]),
("CCAF transcript", "The transcript issued by the Community College of the Air Force, which documents training and education for Air Force and Space Force members. These branches are not covered by the Joint Services Transcript.", ["joint-services-transcript-jst"]),
("CLEP and DSST", "Standardized exams that let students earn college credit by demonstrating knowledge. CLEP is offered by the College Board; DSST by Prometric. Institutions set the passing scores and credit they accept.", ["credit-for-prior-learning-cpl"]),
("Course equivalency", "A decision that a course taken at another institution counts as a specific course in your catalog. Courses without a direct equivalent may count as general education or elective credit, or not at all.", ["articulation-agreement", "transfer-credit-evaluation"]),
("Credential evaluation (NACES)", "A report that translates a foreign academic record into its U.S. equivalent. Members of the National Association of Credential Evaluation Services, such as WES and ECE, produce these reports.", ["gpa-standardization"]),
("Credit for prior learning (CPL)", "College credit awarded for learning gained outside a classroom, such as work experience, certifications, military training, exams or a portfolio. Also called prior learning assessment (PLA).", ["ace-credit-recommendation", "clep-and-dsst"]),
("Credit loss", "Credits a transfer student earned that do not apply toward a degree at the receiving institution. Lost credit adds time and cost; GAO estimated an average 43% loss for transfers in its 2017 study.", ["transfer-credit-evaluation", "reverse-transfer"]),
("DD-214", "The Certificate of Release or Discharge from Active Duty. It summarizes a service member’s record and is often used alongside the JST to verify military training.", ["joint-services-transcript-jst"]),
("Degree audit", "A report that compares a student’s completed and transferred courses with the requirements of their degree program. Common systems include DegreeWorks and uAchieve.", ["student-information-system-sis"]),
("EDI and PESC XML transcripts", "Electronic transcript standards used to exchange academic records between institutions. EDI (SPEEDE) and PESC XML can be processed without manual data entry.", ["transfer-credit-evaluation"]),
("FERPA", "The Family Educational Rights and Privacy Act, the U.S. law that protects the privacy of student education records and limits who may see them without consent.", ["school-official-exception"]),
("First-year (freshman) applicant", "A student applying to college for the first time from high school, a homeschool program or a GED. Their transcripts are high school records, not college credit.", ["transfer-student", "gpa-standardization"]),
("GPA standardization", "Converting grade point averages from different scales (such as 4.0, 5.0, 6.0 or 100-point) to one institutional scale using a documented formula, so every applicant is compared fairly.", ["weighted-and-unweighted-gpa"]),
("HECVAT", "The Higher Education Community Vendor Assessment Toolkit, a standard security questionnaire colleges and universities use to review technology vendors.", ["soc-2"]),
("Human-in-the-loop review", "A process in which software drafts a recommendation and a qualified person approves, changes or rejects it. In LioraAI, staff or faculty approve every credit decision.", ["audit-trail"]),
("Joint Services Transcript (JST)", "The official transcript of military training and occupational experience for the Army, Navy, Marine Corps and Coast Guard, including ACE credit recommendations.", ["ace-credit-recommendation", "ccaf-transcript"]),
("NCAA progress-toward-degree", "Academic benchmarks a student-athlete must meet to remain eligible, such as completing a set percentage of a specific degree program by certain points, plus credit-hour and GPA minimums.", ["transfer-credit-evaluation"]),
("Residency requirement", "The minimum number of credits a student must complete at the degree-granting institution, regardless of how much transfer credit they bring.", ["transfer-credit-evaluation"]),
("Reverse transfer", "Sending credits earned at a four-year institution back to a student’s former community college so it can award an associate degree the student has now qualified for. It requires the student’s consent.", ["credit-loss", "ferpa"]),
("School Certifying Official (SCO)", "The staff member who certifies a student’s enrollment to the Department of Veterans Affairs so they can receive GI Bill benefits. SCOs often coordinate military credit evaluation.", ["joint-services-transcript-jst"]),
("School official exception", "A FERPA provision that lets an institution share education records with a contractor that performs an institutional service, under the institution’s direct control, without student consent.", ["ferpa"]),
("SOC 2", "An independent audit framework from the AICPA that reports on a service provider’s controls for security, availability, processing integrity, confidentiality and privacy.", ["hecvat"]),
("Student information system (SIS)", "The system of record for student data such as admissions, registration, grades and transfer credit. Examples include Ellucian Banner and Colleague, Workday Student, PeopleSoft and Jenzabar.", ["degree-audit"]),
("Transfer credit evaluation", "The process of reviewing a student’s prior college coursework and deciding which courses count, and how, at the receiving institution.", ["course-equivalency", "articulation-agreement"]),
("Transfer student", "Any student bringing credit from another college or university, whatever their class standing. A student with one prior course and a student with 70 credits are both transfer students.", ["first-year-freshman-applicant", "transfer-credit-evaluation"]),
("Transfer yield", "The share of admitted transfer students who enroll. Faster, clearer credit answers are one of the strongest levers on transfer yield.", ["transfer-student"]),
("Weighted and unweighted GPA", "An unweighted GPA uses a standard 4.0 scale for every course. A weighted GPA adds points for Honors, AP, IB or dual-enrollment courses, producing scales up to 5.0 or higher.", ["gpa-standardization"]),
]

